css:
.fq__d { border-top: 1px solid var(--bff-line, rgba(21,38,26,.22)); padding: 1rem 0; max-width: 46rem; }
.fq__d:last-child { border-bottom: 1px solid var(--bff-line, rgba(21,38,26,.22)); }
.fq__s { --keep: 1; font-family: var(--os-font-heading); font-weight: 400; font-size: 1.35rem; line-height: 1.65; cursor: pointer; list-style: none; display: flex; justify-content: space-between; gap: 1rem; color: var(--os-color-heading); }
.fq__s::-webkit-details-marker { display: none; }
.fq__s::after { content: '+'; font-family: var(--os-font-body); font-size: 1.5rem; line-height: 1; }
.fq__d[open] .fq__s::after { content: '\2013'; }
.fq__a { margin: .7rem 0 0; color: var(--os-color-text-muted); }
.fq__a p { margin: .7rem 0 0; max-width: 62ch; }
.fq__a > :first-child, .fq__a .os-rich > :first-child { margin-top: 0; }
@media (max-width: 40rem), (pointer: coarse) { .fq__s { min-height: 2.75rem; align-items: center; } }
